import networkx as nx
import random

def get_graph():
    while True:
        G = nx.Graph()
        G.add_nodes_from(range(22))
        edges = []
        while len(edges) < 27:
            u = random.randint(0, 21)
            v = random.randint(0, 21)
            if u != v and not G.has_edge(u, v):
                G.add_edge(u, v)
                try:
                    cycles = nx.cycle_basis(G)
                    # cycle_basis doesn't guarantee finding the shortest cycle, 
                    # but we can check girth using BFS
                    def get_girth(G):
                        girth = float('inf')
                        for n in G.nodes():
                            dist = {n: 0}
                            queue = [n]
                            parent = {n: None}
                            while queue:
                                curr = queue.pop(0)
                                for neighbor in G.neighbors(curr):
                                    if neighbor not in dist:
                                        dist[neighbor] = dist[curr] + 1
                                        parent[neighbor] = curr
                                        queue.append(neighbor)
                                    elif parent[curr] != neighbor:
                                        girth = min(girth, dist[curr] + dist[neighbor] + 1)
                        return girth

                    if get_girth(G) < 7:
                        G.remove_edge(u, v)
                    else:
                        edges.append((u, v))
                except:
                    G.remove_edge(u, v)

        # Check 3-colorable
        coloring = nx.coloring.greedy_color(G, strategy='largest_first')
        if max(coloring.values()) < 3:
            return list(G.edges())

print(get_graph())

from z3 import *

def solve():
    V = 22
    E = 27

    edges = [[Bool(f"e_{i}_{j}") for j in range(V)] for i in range(V)]

    s = Solver()

    # Symmetry and irreflexivity
    for i in range(V):
        s.add(Not(edges[i][i]))
        for j in range(i+1, V):
            s.add(edges[i][j] == edges[j][i])

    # At least 27 edges
    edge_vars = [If(edges[i][j], 1, 0) for i in range(V) for j in range(i+1, V)]
    s.add(Sum(edge_vars) >= E)

    # 3-colorable
    colors = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(colors[i] >= 0, colors[i] <= 2)
    for i in range(V):
        for j in range(i+1, V):
            s.add(Implies(edges[i][j], colors[i] != colors[j]))

    # Girth >= 7
    # No cycles of length 3
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                s.add(Not(And(edges[i][j], edges[j][k], edges[k][i])))

    # No cycles of length 4
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                for l in range(k+1, V):
                    # Possible 4-cycles among i, j, k, l:
                    # i-j-k-l-i
                    s.add(Not(And(edges[i][j], edges[j][k], edges[k][l], edges[l][i])))
                    # i-j-l-k-i
                    s.add(Not(And(edges[i][j], edges[j][l], edges[l][k], edges[k][i])))
                    # i-k-j-l-i
                    s.add(Not(And(edges[i][k], edges[k][j], edges[j][l], edges[l][i])))

    # No cycles of length 5
    import itertools
    for comb in itertools.combinations(range(V), 5):
        # 5! / (5 * 2) = 12 cycles
        for p in itertools.permutations(comb):
            if p[0] == comb[0] and p[1] < p[-1]:
                s.add(Not(And(edges[p[0]][p[1]], edges[p[1]][p[2]], edges[p[2]][p[3]], edges[p[3]][p[4]], edges[p[4]][p[0]])))

    # No cycles of length 6
    for comb in itertools.combinations(range(V), 6):
        # 6! / (6 * 2) = 60 cycles
        for p in itertools.permutations(comb):
            if p[0] == comb[0] and p[1] < p[-1]:
                s.add(Not(And(edges[p[0]][p[1]], edges[p[1]][p[2]], edges[p[2]][p[3]], edges[p[3]][p[4]], edges[p[4]][p[5]], edges[p[5]][p[0]])))

    print("Solving...")
    if s.check() == sat:
        m = s.model()
        res = []
        for i in range(V):
            for j in range(i+1, V):
                if is_true(m[edges[i][j]]):
                    res.append((i, j))
        print(res)
    else:
        print("UNSAT")

solve()

import random

def solve():
    V = 22
    E = 27

    for attempt in range(10000):
        dist = [[float('inf')] * V for _ in range(V)]
        for i in range(V):
            dist[i][i] = 0

        edges = []
        degrees = [0] * V

        possible_edges = [(i, j) for i in range(V) for j in range(i+1, V)]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if dist[u][v] >= 6:
                # Add edge
                edges.append((u, v))
                degrees[u] += 1
                degrees[v] += 1

                # Update distances
                for i in range(V):
                    for j in range(V):
                        if dist[i][u] + 1 + dist[v][j] < dist[i][j]:
                            dist[i][j] = dist[i][u] + 1 + dist[v][j]
                            dist[j][i] = dist[i][j]
                        if dist[i][v] + 1 + dist[u][j] < dist[i][j]:
                            dist[i][j] = dist[i][v] + 1 + dist[u][j]
                            dist[j][i] = dist[i][j]

                if len(edges) == E:
                    break

        if len(edges) == E:
            # Check 3-colorability
            # Backtracking
            adj = [[] for _ in range(V)]
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)

            colors = [-1] * V
            def color(node):
                if node == V:
                    return True
                used = set()
                for neighbor in adj[node]:
                    if colors[neighbor] != -1:
                        used.add(colors[neighbor])
                for c in range(3):
                    if c not in used:
                        colors[node] = c
                        if color(node + 1):
                            return True
                        colors[node] = -1
                return False

            if color(0):
                print(edges)
                return

    print("UNSAT")

